	/** Tokens held by any of the given users for any of the given clients. */
	async findTokensForClientsAndUsers(
		clientIds: string[],
		userIds: string[],
	): Promise<Array<{ token: string; clientId: string; userId: string }>> {
		if (clientIds.length === 0 || userIds.length === 0) return [];
