	/** Deletes every refresh token of a client. Returns the rows deleted. */
	async deleteAllForClient(clientId: string): Promise<number> {
		const result = await this.delete({ clientId });
		return result.affected ?? 0;
	}
}
"""
open(p,'w').write(s)

p='cli/src/modules/oauth-server/oauth-token.service.ts'
s=open(p).read()
s=s.replace("""	async revokeAccessToken(token""","""	/**
	 * Counts unexpired access tokens per grant. Expiry lives only in the JWT
	 * `exp` claim, so the stored tokens are decoded without verification: the
	 * rows were written by this server. Keys are built by `grantKey`.
	 */
	async countActiveAccessTokensByGrant(
		grants: Array<{ clientId: string; userId: string }>,
	): Promise<Map<string, number>> {
		const counts = new Map<string, number>();
		const wanted = new Set(grants.map(({ clientId, userId }) => grantKey(clientId, userId)));
		const rows = await this.accessTokenRepository.findTokensForClientsAndUsers(
			[...new Set(grants.map((grant) => grant.clientId))],
			[...new Set(grants.map((grant) => grant.userId))],
		);
		const nowSeconds = Date.now() / 1000;

		for (const { token, clientId, userId } of rows) {
			const key = grantKey(clientId, userId);
			if (!wanted.has(key)) continue;
			const exp = this.jwtService.decodeUnverified<{ exp?: unknown } | null>(token)?.exp;
			if (typeof exp === 'number' && exp > nowSeconds) {
				counts.set(key, (counts.get(key) ?? 0) + 1);
			}
		}

		return counts;
	}

	/** Deletes every access and refresh token of a client, for all users. */
	async revokeAllTokensForClient(
		clientId: string,
	): Promise<{ accessTokensRevoked: number; refreshTokensRevoked: number }> {
		const [accessTokensRevoked, refreshTokensRevoked] = await Promise.all([
			this.accessTokenRepository.deleteAllForClient(clientId),
			this.refreshTokenRepository.deleteAllForClient(clientId),
		]);
		return { accessTokensRevoked, refreshTokensRevoked };
	}

	async revokeAccessToken(token""",1)
s=s.replace("""@Service()
export class OAuthTokenService""","""export const grantKey = (clientId: string, userId: string) => `${clientId}:${userId}`;

@Service()
export class OAuthTokenService""",1)
