s=s.replace("""	grantedAt: number;
	scopes: string[];
	/** Consent owner;""","""	grantedAt: number;
	scopes: string[];
	/** Unexpired access tokens the consent owner holds for this client. */
	activeAccessTokenCount: number;
	/** Consent owner;""")
