		);

		const clients: ConnectedOAuthClient[] = consents.map((consent) => {""")
s=s.replace("""				scopes: consent.scope,
				...(listAll""","""				scopes: consent.scope,
				activeAccessTokenCount:
					activeTokenCounts.get(grantKey(consent.clientId, consent.userId)) ?? 0,
				...(listAll""")
s=s.replace("""	/**
	 * Revoke a user's grant for a client:""","""	/**
	 * Revoke all access and refresh tokens of a client, for every user.
	 * The client, consents, and authorization codes stay, so users must
	 * authorize again to get new tokens.
	 */
	async revokeClientTokens(
		clientId: string,
	): Promise<{ accessTokensRevoked: number; refreshTokensRevoked: number }> {
		const exists = await this.oauthClientRepository.existsBy({ id: clientId });
		if (!exists) {
			throw new Error(`OAuth client with ID ${clientId} not found`);
		}

		const result = await this.tokenService.revokeAllTokensForClient(clientId);
		this.logger.info('Revoked all tokens of OAuth client', { clientId, ...result });
		return result;
	}

	/**
	 * Revoke a user's grant for a client:""",1)
open(p,'w').write(s)

p='cli/src/modules/oauth-server/oauth-clients.controller.ts'
s=open(p).read()
