s=s.replace("			scopes: client.scopes,\n","			scopes: client.scopes,\n			activeAccessTokenCount: client.activeAccessTokenCount,\n")
s=s.replace("""	/**
	 * Revoke a user's grant""","""	/**
	 * Revoke all access and refresh tokens of a client, for every user, without
