	@Post('/:clientId/revoke-tokens')
	async revokeClientTokens(
		req: AuthenticatedRequest,
		_res: Response,
		@Param('clientId') clientId: string,
	): Promise<RevokeOAuthClientTokensResponseDto> {
		this.logger.info('Revoking all tokens of OAuth client', { clientId, userId: req.user.id });

		try {
			return await this.oauthServerService.revokeClientTokens(clientId);
		} catch (error) {
			if (error instanceof Error && error.message.includes('not found')) {
				throw new NotFoundError(`OAuth client with ID ${clientId} not found`);
			}
			throw error;
		}
	}

	/**
	 * Revoke a user's grant""",1)
open(p,'w').write(s)
